def calc(expr):
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if c.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            tokens.append(('num', int(expr[i:j])))
            i = j
            continue
        if c in '+-*/()':
            tokens.append((c, c))
            i += 1
            continue
        raise ValueError(f"Unexpected character: {c}")

    pos = 0

    def peek():
        if pos < len(tokens):
            return tokens[pos]
        return None

    def parse_expr():
        nonlocal pos
        val = parse_term()
        while True:
            tok = peek()
            if tok and tok[0] in ('+', '-'):
                pos += 1
                rhs = parse_term()
                if tok[0] == '+':
                    val = val + rhs
                else:
                    val = val - rhs
            else:
                break
        return val

    def parse_term():
        nonlocal pos
        val = parse_factor()
        while True:
            tok = peek()
            if tok and tok[0] in ('*', '/'):
                pos += 1
                rhs = parse_factor()
                if tok[0] == '*':
                    val = val * rhs
                else:
                    # integer division truncating toward zero
                    q = abs(val) // abs(rhs)
                    if (val < 0) != (rhs < 0):
                        q = -q
                    val = q
            else:
                break
        return val

    def parse_factor():
        nonlocal pos
        neg = False
        while True:
            tok = peek()
            if tok and tok[0] == '-':
                pos += 1
                neg = not neg
            else:
                break
        val = parse_atom()
        if neg:
            val = -val
        return val

    def parse_atom():
        nonlocal pos
        tok = peek()
        if tok is None:
            raise ValueError("Unexpected end of expression")
        if tok[0] == 'num':
            pos += 1
            return tok[1]
        if tok[0] == '(':
            pos += 1
            val = parse_expr()
            tok2 = peek()
            if tok2 is None or tok2[0] != ')':
                raise ValueError("Expected closing parenthesis")
            pos += 1
            return val
        raise ValueError(f"Unexpected token: {tok}")

    result = parse_expr()
    if pos != len(tokens):
        raise ValueError("Unexpected trailing tokens")
    return result

